INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Chair_Squat', 'Chair Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be y'),
('Chair_Upper_Body_Stretch', 'Chair Upper Body Stretch', 'shoulders', ARRAY['arms','chest']::text[], 'other', 'stretching', 'beginner', 'Sit on the edge of a chair, gripping the back of it. Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.'),
('Chest_And_Front_Of_Shoulder_Stretch', 'Chest And Front Of Shoulder Stretch', 'chest', ARRAY['shoulders']::text[], 'other', 'stretching', 'beginner', 'Start off by standing with your legs together, holding a bodybar or a broomstick. Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down. Carefully lift the pole up and behind your head.'),
('Chest_Push_from_3_point_stance', 'Chest Push from 3 point stance', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you. To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw. As you execute the second step, explosively release the ball forward as hard as possible.'),
('Chest_Push_multiple_response', 'Chest Push (multiple response)', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest. Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible. Follow through by falling forward, catching yourself with your hands. Immediately return to an upright position. Repeat for the desired number of repetitions.'),
('Chest_Push_single_response', 'Chest Push (single response)', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a kneeling position holding the medicine ball with both hands tightly into the chest. Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible. Follow through by falling forward, catching yourself with your hands.'),
('Chest_Push_with_Run_Release', 'Chest Push with Run Release', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position. While taking your first step draw the medicine ball into your chest. As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!'),
('Chest_Stretch_on_Stability_Ball', 'Chest Stretch on Stability Ball', 'chest', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Get on your hands and knees next to an exercise ball. Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position. Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.'),
('Childs_Pose', 'Child''s Pose', 'back', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Get on your hands and knees, walk your hands in front of you. Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine. Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.'),
('Chin-Up', 'Chin-Up', 'back', ARRAY['arms','arms','back']::text[], 'bodyweight', 'strength', 'beginner', 'Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement. As you breathe out, pull your torso up until your head i'),
('Chin_To_Chest_Stretch', 'Chin To Chest Stretch', 'other', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Get into a seated position on the floor. Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.'),
('Circus_Bell', 'Circus Bell', 'shoulders', ARRAY['arms','legs','legs','back','back','arms']::text[], 'other', 'strongman', 'expert', 'The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands. Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand. Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, lean'),
('Clean', 'Clean', 'legs', ARRAY['legs','arms','legs','back','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.  Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.'),
('Clean_Deadlift', 'Clean Deadlift', 'legs', ARRAY['arms','legs','back','back','legs','back']::text[], 'barbell', 'olympic weightlifting', 'beginner', 'Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible. Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant bac'),
('Clean_Pull', 'Clean Pull', 'legs', ARRAY['arms','legs','legs','back','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to abov'),
('Clean_Shrug', 'Clean Shrug', 'back', ARRAY['arms','shoulders']::text[], 'barbell', 'olympic weightlifting', 'beginner', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.'),
('Clean_and_Jerk', 'Clean and Jerk', 'shoulders', ARRAY['core','legs','legs','back','legs','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Ne'),
('Clean_and_Press', 'Clean and Press', 'shoulders', ARRAY['core','legs','legs','legs','back','back','legs','shoulders','back','arms']::text[], 'barbell', 'strength', 'intermediate', 'Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position. Begin to pull the bar by extending the knees. Move your hips fo'),
('Clean_from_Blocks', 'Clean from Blocks', 'legs', ARRAY['legs','legs','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out. As full extension is achieved,'),
('Clock_Push-Up', 'Clock Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'intermediate', 'Move into a prone position on the floor, supporting your weight on your hands and toes. Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest toward the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side. As you accel'),
('Close-Grip_Barbell_Bench_Press', 'Close-Grip Barbell Bench Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement. After a second pause, bring the bar back to the starting position as you breat'),
('Close-Grip_Dumbbell_Press', 'Close-Grip Dumbbell Press', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor. Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position. Initiat'),
('Close-Grip_EZ-Bar_Curl_with_Band', 'Close-Grip EZ-Bar Curl with Band', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position. While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps h'),
('Close-Grip_EZ-Bar_Press', 'Close-Grip EZ-Bar Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Lie on a flat bench with an EZ bar loaded to an appropriate weight. Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position. Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement. Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale. Repeat.'),
('Close-Grip_EZ_Bar_Curl', 'Close-Grip EZ Bar Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted'),
('Close-Grip_Front_Lat_Pulldown', 'Close-Grip Front Lat Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to you'),
('Close-Grip_Push-Up_off_of_a_Dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'arms', ARRAY['core','chest','shoulders']::text[], 'bodyweight', 'strength', 'intermediate', 'Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position. Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag. Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step. After a pause at the contracted position, repeat t'),
('Close-Grip_Standing_Barbell_Curl', 'Close-Grip Standing Barbell Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands, palms up and a few inches apart. Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement. Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip:'),
('Cocoons', 'Cocoons', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position. To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion. After a brief pause, return to the starting position.'),
('Conans_Wheel', 'Conan''s Wheel', 'legs', ARRAY['core','arms','legs','arms','back','shoulders','back']::text[], 'other', 'strongman', 'intermediate', 'With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms. Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.'),
('Concentration_Curls', 'Concentration Curls', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor. Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position. While holding the upper arm stationary'),
('Cross-Body_Crunch', 'Cross-Body Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on your back and bend your knees about 60 degrees. Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position. Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember'),
('Cross_Body_Hammer_Curl', 'Cross Body Hammer Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in. While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second. Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm. Continue alternating in this fashion until'),
('Cross_Over_-_With_Bands', 'Cross Over - With Bands', 'chest', ARRAY['arms','shoulders']::text[], 'bands', 'strength', 'beginner', 'Secure an exercise band around a stationary post. While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band. Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position. While keeping your arms straight, bring them across your '),
('Crossover_Reverse_Lunge', 'Crossover Reverse Lunge', 'back', ARRAY['core','legs','legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'Stand with your feet shoulder width apart. This will be your starting position. Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg. After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.'),
('Crucifix', 'Crucifix', 'shoulders', ARRAY['arms']::text[], 'other', 'strongman', 'beginner', 'In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different. Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be '),
('Crunch_-_Hands_Overhead', 'Crunch - Hands Overhead', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves. Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position. Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and h'),
('Crunch_-_Legs_On_Exercise_Ball', 'Crunch - Legs On Exercise Ball', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle. Place your feet three to four inches apart and point your toes inward so they touch. Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position. Begin to roll your shoulders off the floor and co'),
('Crunches', 'Crunches', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch. Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders of'),
('Cuban_Press', 'Cuban Press', 'shoulders', ARRAY['back']::text[], 'dumbbell', 'strength', 'intermediate', 'Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position. To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor. Now press the dumbbells by ex'),
('Dancers_Stretch', 'Dancer''s Stretch', 'back', ARRAY['legs','legs']::text[], 'other', 'stretching', 'beginner', 'Sit up on the floor. Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor. Place your left arm on your right leg and your right hand on the floor. Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.'),
('Dead_Bug', 'Dead Bug', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin lying on your back with your hands extended above you toward the ceiling. Bring your feet, knees, and hips up to 90 degrees. Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position. Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground. Maintain the position of your lumbar and pelv'),
('Deadlift_with_Bands', 'Deadlift with Bands', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knee'),
('Deadlift_with_Chains', 'Deadlift with Chains', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and ben'),
('Decline_Barbell_Bench_Press', 'Decline Barbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.'),
('Decline_Close-Grip_Bench_To_Skull_Crusher', 'Decline Close-Grip Bench To Skull Crusher', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack. Now lower the bar down to your lower chest as you b'),
('Decline_Crunch', 'Decline Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'intermediate', 'Secure your legs at the end of the decline bench and lie down. Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, '),
('Decline_Dumbbell_Bench_Press', 'Decline Dumbbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times'),
('Decline_Dumbbell_Flyes', 'Decline Dumbbell Flyes', 'chest', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms'),
('Decline_Dumbbell_Triceps_Extension', 'Decline Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down')
